 "content": "def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    vals = {}
    for r in range(h):
        for c in range(w):
            vals.setdefault(grid[r][c], []).append((r,c))
    bg = max(vals, key=lambda x: len(vals[x]))
    for color, pts in vals.items():
        if color == bg:
            continue
        directions = set()
        pset = set(pts)
        for r,c in pts:
            for dr,dc in ((1,1),(1,-1)):
                if (r+dr,c+dc) in pset:
                    directions.add((dr,dc))
        for dr,dc in directions:
            for r,c in pts:
                if (r-dr,c-dc) not in pset:
